'use strict';
// Gameplay stays synchronous and testable. The UI replays the recorded state changes.
async function playAction(fn){
 if(busy||modal)return;
 const before=clone(S);let queue;
 try{queue=captureAction(fn)}catch(error){S=before;render();console.error(error);return}
 if(!queue.length){render();return}
 const result=S,resultModal=modal;busy=true;modal=null;S=before;phaseLabel=queue[0].label||'Resolving action';render();if(window.innerWidth<=700)document.querySelector('.board-wrap')?.scrollIntoView({block:'center',behavior:'instant'});
 try{for(const frame of queue){const previous=visualSnapshot();S=frame.state;phaseLabel=frame.label||phaseLabel;render();await animateFrame(frame,previous)}}
 finally{S=result;modal=resultModal;busy=false;phaseLabel='';render()}
}
function visualSnapshot(){const units=new Map,objects=new Map;document.querySelectorAll('[data-piece]').forEach(el=>units.set(el.dataset.piece,{rect:el.getBoundingClientRect(),node:el.cloneNode(true)}));document.querySelectorAll('.cell .scenery').forEach(el=>{const cell=el.closest('.cell');objects.set(cell.dataset.x+','+cell.dataset.y,{rect:cell.getBoundingClientRect(),node:el.parentElement.cloneNode(true)})});return{units,objects}}
function tileElement(x,y){return document.querySelector(`.cell[data-x="${x}"][data-y="${y}"]`)}
function animateNode(el,keyframes,duration,extra={}){if(!el?.animate)return Promise.resolve();return el.animate(keyframes,{duration,easing:'ease-in-out',...extra}).finished.catch(()=>{})}
function ghost(item){const node=item.node.cloneNode(true);node.classList.add('fx-ghost');node.setAttribute('aria-hidden','true');Object.assign(node.style,{left:item.rect.left+'px',top:item.rect.top+'px',width:item.rect.width+'px',height:item.rect.height+'px'});document.body.appendChild(node);return node}
async function animateFrame(f,previous){
 if(f.type==='dialogue'){await showSpeech(f.speaker,f.text);return}
 const reduced=reducedMotion();
 const durations={move:230,slide:240,current:280,push:310,shot:370,melee:300,grapple:390,cast:350,damage:240,blast:520,column:490,phase:360,water:260,fire:260,grow:360};
 const ms=reduced?85:(durations[f.type]||300)/visualSpeed,jobs=[],cleanup=[];
 const acting=f.id?document.querySelector(`[data-piece="${f.id}"]`)?.closest('.cell'):f.from?tileElement(f.from.x,f.from.y):null;if(acting)acting.classList.add('resolving');
 const animate=(el,k,opts={})=>{jobs.push(animateNode(el,k,ms,opts));return el};
 const ring=(x,y,color='#e6ad59')=>{const c=tileElement(x,y);if(!c)return;const el=document.createElement('span');el.className='fx-ring';el.style.borderColor=color;c.appendChild(el);cleanup.push(el);animate(el,[{transform:reduced?'none':'scale(.3)',opacity:1},{transform:reduced?'none':'scale(1.45)',opacity:0}])};
 const particles=(x,y,color,count=7,kind='spark')=>{const c=tileElement(x,y);if(!c||reduced)return;for(let n=0;n<count;n++){const p=document.createElement('i');p.className='fx-particle '+kind;p.style.background=color;c.appendChild(p);cleanup.push(p);const angle=(n/count)*Math.PI*2,reach=18+(n%3)*10;animate(p,[{transform:'translate(0,0) scale(.4)',opacity:0},{opacity:1,offset:.12},{transform:`translate(${Math.cos(angle)*reach}px,${Math.sin(angle)*reach-10}px) scale(${kind==='leaf'?'.6':'.1'}) rotate(${n*71}deg)`,opacity:0}],{easing:'cubic-bezier(.15,.6,.35,1)'})}};
 if(['move','slide','current','push'].includes(f.type)){const u=S.units.find(u=>u.id===f.id);if(u){particles(u.x,u.y,f.type==='current'?'#d9f1e3':'#d4cca5',f.type==='move'?3:6,f.type==='current'?'drop':'dust');const el=document.querySelector(`[data-piece="${u.id}"] .character-body`);if(el&&!reduced)animate(el,[{transform:'translateY(0) rotate(-3deg)'},{transform:'translateY(-3px) rotate(3deg)',offset:.5},{transform:'translateY(0) rotate(0)'}])}}
 const number=(x,y,text,color)=>{const c=tileElement(x,y);if(!c)return;const el=document.createElement('span');el.className='fx-number';el.textContent=text;el.style.color=color;c.appendChild(el);cleanup.push(el);animate(el,[{transform:'translateY(0)',opacity:1},{transform:reduced?'none':'translateY(-25px)',opacity:0}])};
 for(const el of document.querySelectorAll('[data-piece]')){const old=previous.units.get(el.dataset.piece);if(!old)continue;const box=el.getBoundingClientRect(),scale=box.width/(el.offsetWidth||box.width)||1,dx=(old.rect.left-box.left)/scale,dy=(old.rect.top-box.top)/scale;if((dx||dy)&&!reduced){el.style.zIndex='9';animate(el,[{transform:`translate(${dx}px,${dy}px)`},{transform:'translate(0,0)'}])}}
 for(const[id,item]of previous.units)if(!document.querySelector(`[data-piece="${id}"]`)){const el=ghost(item);cleanup.push(el);animate(el,[{opacity:1,transform:'scale(1)'},{opacity:0,transform:reduced?'none':'scale(.55) rotate(12deg)'}])}
 if(['shot','grapple','cast'].includes(f.type)&&f.from&&f.to){
  const source=tileElement(f.from.x,f.from.y),target=tileElement(f.to.x,f.to.y),board=document.querySelector('.board');
  if(source&&target&&board){
   const a=source.getBoundingClientRect(),b=target.getBoundingClientRect(),box=board.getBoundingClientRect();
   // Use a fixed overlay so lines also remain aligned inside scaled QA frames.
   const layer=document.createElementNS('http://www.w3.org/2000/svg','svg');layer.classList.add('fx-line');layer.setAttribute('aria-hidden','true');layer.setAttribute('viewBox',`0 0 ${box.width} ${box.height}`);Object.assign(layer.style,{left:box.left+'px',top:box.top+'px',width:box.width+'px',height:box.height+'px'});
   const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',a.left+a.width/2-box.left);line.setAttribute('y1',a.top+a.height/2-box.top);line.setAttribute('x2',b.left+b.width/2-box.left);line.setAttribute('y2',b.top+b.height/2-box.top);line.setAttribute('stroke',(f.type==='shot'||S.units.find(u=>u.id===f.id)?.team==='enemy')?'#e6794c':f.type==='grapple'?'#e1c27e':f.role==='tidecaller'?'#78bfce':'#a9c17f');line.setAttribute('stroke-width',f.type==='melee'?'8':'4');line.setAttribute('stroke-linecap','round');layer.appendChild(line);document.body.appendChild(layer);cleanup.push(layer);const length=Math.max(1,Math.hypot(b.left-a.left,b.top-a.top));if(!reduced){const shot=document.createElement('i');shot.className='fx-projectile '+f.type;Object.assign(shot.style,{left:(a.left+a.width/2)+'px',top:(a.top+a.height/2)+'px'});document.body.appendChild(shot);cleanup.push(shot);animate(shot,[{transform:'translate(-50%,-50%) scale(.5)',opacity:0},{opacity:1,offset:.12},{transform:`translate(calc(-50% + ${b.left-a.left}px),calc(-50% + ${b.top-a.top}px)) scale(1)`,opacity:0}],{easing:'cubic-bezier(.3,0,.7,1)'});particles(f.to.x,f.to.y,f.type==='shot'?'#edb86f':'#acd3c4',6)}line.style.strokeDasharray=length;animate(line,reduced?[{opacity:1},{opacity:.2}]:[{strokeDashoffset:length,opacity:1},{strokeDashoffset:0,opacity:1,offset:.6},{strokeDashoffset:f.type==='grapple'?-length:0,opacity:0}]);
   const attacker=document.querySelector(`[data-piece="${f.id}"]`);if(attacker&&!reduced)animate(attacker,[{transform:'translate(0,0)'},{transform:`translate(${Math.sign(b.left-a.left)*8}px,${Math.sign(b.top-a.top)*8}px)`,offset:.4},{transform:'translate(0,0)'}]);
  }
 }
 if(f.type==='melee'&&f.from&&f.to){const target=tileElement(f.to.x,f.to.y),attacker=document.querySelector(`[data-piece="${f.id}"]`);if(target){const slash=document.createElement('span');slash.className='fx-sweep';target.appendChild(slash);cleanup.push(slash);animate(slash,reduced?[{opacity:1},{opacity:0}]:[{transform:'rotate(-100deg) scale(.4)',opacity:0},{transform:'rotate(-15deg) scale(1.2)',opacity:1,offset:.5},{transform:'rotate(100deg) scale(.9)',opacity:0}]);particles(f.to.x,f.to.y,'#f1d393',8);if(attacker&&!reduced){const dx=(f.to.x-f.from.x)*13,dy=(f.to.y-f.from.y)*13;animate(attacker,[{transform:`translate(${-dx*.3}px,${-dy*.3}px)`},{transform:`translate(${dx}px,${dy}px)`,offset:.45},{transform:'translate(0,0)'}])}}}
 if(f.type==='cast'&&f.from){ring(f.from.x,f.from.y,'#b1dbcd');particles(f.from.x,f.from.y,'#e5dcaa',5,'leaf')}
 if(f.type==='teleport'){for(const[id,old]of previous.units){const now=S.units.find(u=>u.id===id),el=document.querySelector(`[data-piece="${id}"]`);if(now&&el&&(Math.abs(old.rect.left-el.getBoundingClientRect().left)>2||Math.abs(old.rect.top-el.getBoundingClientRect().top)>2)){particles(now.x,now.y,'#d5c2e4',12);animate(el,[{opacity:0,filter:'brightness(2)'},{opacity:1,filter:'brightness(1)'}])}}}
 if(f.type==='phase'&&f.label){const banner=document.createElement('div');banner.className='fx-phase-banner';banner.innerHTML=esc(f.label)+'<small>THE LAST CURRENT · ROUND '+S.round+'</small>';document.body.appendChild(banner);cleanup.push(banner);jobs.push(animateNode(banner,reduced?[{opacity:1},{opacity:0}]:[{opacity:0,transform:'translate(-50%,calc(-50% + 8px))'},{opacity:1,transform:'translate(-50%,-50%)',offset:.25},{opacity:1,offset:.75},{opacity:0,transform:'translate(-50%,calc(-50% - 6px))'}],reduced?100:720/visualSpeed))}
 if(f.type==='damage'){const tile=tileElement(f.x,f.y);if(tile&&!reduced){const flash=document.createElement('span');flash.className='fx-hit';tile.appendChild(flash);cleanup.push(flash);animate(flash,[{opacity:1,transform:'scale(.4)'},{opacity:0,transform:'scale(1.5)'}])}particles(f.x,f.y,'#d09c6c',6);ring(f.x,f.y,'#d77356');number(f.x,f.y,'−'+f.amount,'#b64835');const p=document.querySelector(`[data-piece="${f.id}"]`);if(p)animate(p,[{filter:'brightness(2) sepia(1)'},{filter:'none'}])}
 if(['shield','charm','haste','teleport','evacuate'].includes(f.type)){const u=S.units.find(u=>u.id===f.id);ring(f.x??u?.x,f.y??u?.y,f.type==='charm'?'#b391ac':'#80b3a4')}
 if(f.type==='heal'){particles(f.x,f.y,'#8ec5a0',8,'leaf');ring(f.x,f.y,'#66a38c');number(f.x,f.y,'+'+f.amount,'#267d67')}
 if(f.type==='collect'){ring(f.x,f.y,'#dfb64f');number(f.x,f.y,'✦','#a58024')}
 if(f.type==='blast'){particles(f.x,f.y,'#e6ad65',16);const b=document.querySelector('.board');if(b&&!reduced)animate(b,[{transform:'translate(0,0)'},{transform:'translate(-3px,2px)',offset:.2},{transform:'translate(3px,-2px)',offset:.4},{transform:'translate(-1px,1px)',offset:.7},{transform:'translate(0,0)'}]);for(const[dx,dy]of [[0,0],...DIR]){const c=tileElement(f.x+dx,f.y+dy);if(c){animate(c,[{backgroundColor:'#fff2c2'},{backgroundColor:'#eb995b',offset:.4},{backgroundColor:''}]);ring(f.x+dx,f.y+dy,'#edaa54')}}}
 if(['grow','plant','spawn'].includes(f.type)){particles(f.x,f.y,'#9db57d',9,'leaf');const c=tileElement(f.x,f.y),p=c?.querySelector('.object, .unit-sprite');if(p)animate(p,reduced?[{opacity:.25},{opacity:1}]:[{transform:'scale(.1) translateY(10px)',opacity:.2},{transform:'scale(1.12)',opacity:1,offset:.75},{transform:'scale(1)'}]);ring(f.x,f.y,'#8ea76d')}
 if(['fire','rain','water','lever','wind','collision'].includes(f.type)){const color=f.type==='fire'?'#df8751':['rain','water'].includes(f.type)?'#6eafc2':'#c9ad6b';ring(f.x,f.y,color);if(f.type==='wind')for(let n=1;n<Math.max(width(),height());n++){const dx=f.dx??1,dy=f.dy??0;if(inside(f.x+dx*n,f.y+dy*n))ring(f.x+dx*n,f.y+dy*n,'#a2bfa5')}}
 if(['gate','break'].includes(f.type)){particles(f.x,f.y,'#bbb38d',8,'dust');const item=previous.objects.get(f.x+','+f.y);if(item){const el=ghost(item);cleanup.push(el);animate(el,reduced?[{opacity:1},{opacity:0}]:[{opacity:1,transform:'translateY(0)'},{opacity:0,transform:f.type==='gate'?'translateY(-30px)':'scale(.5) rotate(15deg)'}])}}
 if(f.type==='column'){const item=previous.objects.get(f.x+','+f.y);if(item){const el=ghost(item);cleanup.push(el);const c=tileElement(f.x,f.y);const art=c?.querySelector('.object');if(art)art.style.visibility='hidden';animate(el,[{transform:'translate(0,0) rotate(0)',opacity:1},{transform:reduced?'none':`translate(${f.dx*item.rect.width}px,${f.dy*item.rect.height}px) rotate(${f.dx?f.dx*90:f.dy*100}deg)`,opacity:0}]);for(let n=1;n<=2;n++)ring(f.x+f.dx*n,f.y+f.dy*n,'#c8b88b')}}
 if(f.type==='objectMove'){const c=tileElement(f.to.x,f.to.y),el=c?.querySelector('.object'),a=tileElement(f.from.x,f.from.y)?.getBoundingClientRect(),b=c?.getBoundingClientRect();if(el&&a&&b&&!reduced)animate(el,[{transform:`translate(${a.left-b.left}px,${a.top-b.top}px)`},{transform:'translate(0,0)'}])}
 if(!jobs.length)jobs.push(new Promise(resolve=>setTimeout(resolve,ms)));
 await Promise.all(jobs);cleanup.forEach(el=>el.remove());acting?.classList.remove('resolving');
}
function clearRoutePreview(){document.querySelectorAll('.path-step,.path-landing').forEach(el=>el.classList.remove('path-step','path-landing'));document.querySelectorAll('.path-number,.route-line').forEach(el=>el.remove());const caption=document.getElementById('routecaption');if(caption?.dataset.default)caption.textContent=caption.dataset.default}
function showRoutePreview(x,y){clearRoutePreview();if(busy||modal||inspectMode||mode!=='move')return;const u=S.units.find(u=>u.id===selected&&u.hp>0);if(!u)return;const route=moveOptions(u).get(key(x,y));if(!route)return;route.trace.forEach((point,index)=>{const el=tileElement(point.x,point.y);if(!el)return;el.classList.add('path-step');if(!el.querySelector('.path-number')){const n=document.createElement('span');n.className='path-number';n.setAttribute('aria-hidden','true');n.textContent=index+1;el.appendChild(n)}});tileElement(route.x,route.y)?.classList.add('path-landing');const board=document.querySelector('.board'),bounds=board?.getBoundingClientRect();if(board&&bounds&&route.trace.length>1){const line=document.createElementNS('http://www.w3.org/2000/svg','svg');line.classList.add('route-line');line.setAttribute('viewBox',`0 0 ${bounds.width} ${bounds.height}`);line.setAttribute('aria-hidden','true');const points=route.trace.map(p=>{const b=tileElement(p.x,p.y)?.getBoundingClientRect();return b?[b.left+b.width/2-bounds.left,b.top+b.height/2-bounds.top]:null}).filter(Boolean);const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',points.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' '));line.appendChild(path);board.appendChild(line)}const caption=document.getElementById('routecaption');if(caption){caption.dataset.default||=caption.textContent;caption.textContent=routeDescription(route)}}
function attachCellControls(){
 const wrap=document.querySelector('.board-wrap');if(wrap)wrap.onclick=e=>{if(!busy&&!modal&&!inspectMode&&!e.target.closest('.cell'))deselect()};
 for(const el of document.querySelectorAll('[data-x]')){
  const x=+el.dataset.x,y=+el.dataset.y;let timer=null,held=false,start=null;
  const cancel=()=>{clearTimeout(timer);timer=null};
  el.onclick=()=>{cancel();if(held){held=false;return}if(busy||modal)return;if(inspectMode)inspectAt(x,y);else playAction(()=>clickCell(x,y))};
  el.oncontextmenu=e=>{e.preventDefault();cancel();if(busy)return;held=true;inspectAt(x,y)};
  el.onpointerdown=e=>{held=false;start={x:e.clientX,y:e.clientY};if(e.pointerType==='mouse'&&e.button!==0)return;timer=setTimeout(()=>{held=true;inspectAt(x,y)},550)};
  el.onpointermove=e=>{if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>10)cancel()};
  el.onpointerup=cancel;el.onpointercancel=cancel;el.onpointerenter=e=>{if(e.pointerType==='mouse'){showRoutePreview(x,y)}};el.onpointerleave=()=>{cancel();clearRoutePreview()};el.onfocus=()=>{showRoutePreview(x,y)};el.onblur=clearRoutePreview;
  el.onkeydown=e=>{if(e.key==='F1'||(e.shiftKey&&e.key==='F10')){e.preventDefault();inspectAt(x,y)}};
 }
}

async function showSpeech(speaker,text){const actor=[...S.units].reverse().find(u=>u.role===speaker&&u.hp>0&&!u.escaped),cell=actor?tileElement(actor.x,actor.y):null;const bubble=document.createElement('div');bubble.className='speech-bubble '+(cell?'anchored':'radio');bubble.setAttribute('role','status');const meta=ROLES[speaker];bubble.innerHTML=`<span class="speech-portrait">${meta?portrait(speaker):'<span class="radio-face">☼</span>'}</span><div><strong>${esc(meta?.name||speaker)} <small>${actor?meta?.title||'':'RADIO'}</small></strong><p>${esc(text)}</p><button class="speech-next">Continue ↵</button></div>`;document.body.appendChild(bubble);const box=cell?.getBoundingClientRect();if(box){const w=Math.min(310,window.innerWidth-24);bubble.style.width=w+'px';bubble.style.left=Math.max(12,Math.min(window.innerWidth-w-12,box.left+box.width/2-w/2))+'px';bubble.style.top=Math.max(12,Math.min(window.innerHeight-bubble.offsetHeight-16,box.top-bubble.offsetHeight-12))+'px';bubble.style.setProperty('--tail',Math.max(20,Math.min(w-20,box.left+box.width/2-parseFloat(bubble.style.left)))+'px')}await new Promise(resolve=>{const keyAdvance=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopImmediatePropagation();done()}};const done=()=>{document.removeEventListener('keydown',keyAdvance,true);resolve()};document.addEventListener('keydown',keyAdvance,true);bubble.querySelector('button').onclick=done});bubble.remove()}
